node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {artifactDigest, taskContractDigest, sha256} from './scripts/remediation/board.mjs';
const dir='docs/remediation/evidence/W06.08/', read=p=>JSON.parse(readFileSync(p,'utf8'));
const artifact=read(dir+'artifact.json'), contract=read('docs/remediation/design/W06.08/task-contract-v1.json'), lead=read(dir+'lead-scoped-diff.json'), worker=read(dir+'worker.json'), baseline=read(dir+'baseline.json');
function applyUnified(content,patch){
 const lines=content.split('\n'), out=[], ps=patch.split('\n');let cursor=0,hunks=0;
 for(let i=0;i<ps.length;i++){
  const h=/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(ps[i]);if(!h)continue;
  const oldLength=Number(h[2]??1),newLength=Number(h[4]??1),start=Number(h[1])-(oldLength===0?0:1);
  if(start<cursor)throw new Error('overlapping hunk');out.push(...lines.slice(cursor,start));cursor=start;let oldCount=0,newCount=0;
  while(oldCount<oldLength||newCount<newLength){const p=ps[++i];if(typeof p!=='string')throw new Error('short patch');
   if(p[0]===' '||p[0]==='-'){if(lines[cursor]!==p.slice(1))throw new Error('context mismatch at '+cursor);cursor++;oldCount++;}
   if(p[0]===' '||p[0]==='+'){out.push(p.slice(1));newCount++;}
   if(![' ','-','+','\\'].includes(p[0]))throw new Error('invalid patch line');
  }
  if(oldCount!==oldLength||newCount!==newLength)throw new Error('hunk count');hunks++;
 }
 if(!hunks)throw new Error('no hunks');out.push(...lines.slice(cursor));return out.join('\n');
}
const pins=artifact.files.map(p=>({path:p.path,matches:sha256(readFileSync(p.path))===p.sha256}));
const reconstructed=lead.files.map(f=>{
 const provenance=f.reconstructed_from, historical=read(provenance.path), original=historical.before_sources.files.find(x=>x.path===f.path);
 const allDiff=historical.checks.find(x=>x.id===provenance.check_id).output;
 const marker='--- before/'+f.path+'\n',start=allDiff.indexOf(marker),end=allDiff.indexOf('\n--- before/',start+marker.length);
 if(start<0)throw new Error('missing historical patch');const patch=allDiff.slice(start,end<0?undefined:end);
 const admitted=applyUnified(original.content,patch), final=applyUnified(admitted,f.diff), actual=readFileSync(f.path,'utf8');
 const imports=text=>text.split('\n').filter(x=>x.startsWith('import '));
 return {path:f.path,historical_proof_matches:sha256(readFileSync(provenance.path))===provenance.sha256,original_matches:sha256(original.content)===provenance.before_content_sha256,
 admission_sha256:sha256(admitted),expected_admission_sha256:f.before_sha256,preflight_matches:baseline.files.some(x=>x.path===f.path&&x.sha256===sha256(admitted)),
 reconstructed_final_sha256:sha256(final),current_sha256:sha256(actual),expected_final_sha256:f.after_sha256,final_bytes_match:final===actual,
 imports_unchanged:JSON.stringify(imports(admitted))===JSON.stringify(imports(actual)),diff_sha256:sha256(f.diff)};
});
const result={at:new Date().toISOString(),artifact_digest:artifactDigest(artifact),expected_digest:artifact.digest,contract_digest:taskContractDigest(contract),expected_contract:artifact.contract_digest,pin_count:pins.length,all_pins_match:pins.every(x=>x.matches),bad_pins:pins.filter(x=>!x.matches),worker_sha256:sha256(readFileSync(dir+'worker.json')),lead_diff_sha256:sha256(readFileSync(dir+'lead-scoped-diff.json')),reconstructed,worker_checks:worker.checks.map(x=>({id:x.id,command:x.command,exit_code:x.exit_code,output_sha256:sha256(x.output),output_length:x.output.length})),manifest_paths:artifact.files.map(x=>x.path)};
const pass=result.artifact_digest===result.expected_digest&&result.contract_digest===result.expected_contract&&result.all_pins_match&&result.worker_sha256==='3800454801bd0f924b815883c1eb26751c2842fd66bbdcac345e69cb2c1a2521'&&reconstructed.every(x=>x.historical_proof_matches&&x.original_matches&&x.admission_sha256===x.expected_admission_sha256&&x.preflight_matches&&x.final_bytes_match&&x.current_sha256===x.expected_final_sha256)&&worker.checks.every(x=>x.exit_code===0);
console.log(JSON.stringify({...result,pass},null,2));if(!pass)process.exitCode=1;
NODE
